\n  </tr>\r\n  <tr>\r\n   <td colspan=\"2\" rowspan=\"1\">\r\n   <h2>INGRESOS</h2>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td colspan=\"2\" rowspan=\"1\">variable_ficha_ingresos</td>\r\n  </tr>\r\n  <tr>\r\n   <td>TOTAL EGRESOS:</td>\r\n   <td style=\"text-align:right\">variable_total_ingresos</td>\r\n  </tr>\r\n  <tr>\r\n   <td colspan=\"2\" rowspan=\"1\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n   <td colspan=\"2\" rowspan=\"1\">\r\n   <h2>EGRESOS</h2>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td colspan=\"2\" rowspan=\"1\">variable_ficha_egresos</td>\r\n  </tr>\r\n  <tr>\r\n   <td>TOTAL EGRESOS:</td>\r\n   <td style=\"text-align:right\">variable_total_egresos</td>\r\n  </tr>\r\n  <tr>\r\n   <td colspan=\"2\" rowspan=\"1\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <h3>RESULTADO DEL PERIODO:</h3>\r\n   </td>\r\n   <td style=\"text-align:right\">variable_resultado_del_periodo</td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n','',''),(800,510,'alta','PLD.- Formato de Alerta','<div style=\"text-align: left;\">\r\n<hr /><span style=\"font-family:courier new,courier,monospace\">Fecha:</span>variable_fecha_larga_actual</div>\r\n\r\n<div style=\"text-align: left;\"><span style=\"font-family:courier new,courier,monospace\">Hora:</span>variable_hora_actual</div>\r\n\r\n<div style=\"text-align: left;\"><span style=\"font-family:courier new,courier,monospace\">Ciudad:</span>variable_ciudad_de_la_entidad</div>\r\n\r\n<div style=\"text-align: left;\"><span style=\"font-family:courier new,courier,monospace\">C. Oficial de Cumplimento:</span>variable_oficial</div>\r\n\r\n<div style=\"text-align: left;\">&nbsp;</div>\r\n\r\n<h2 style=\"text-align: center;\"><span style=\"font-family:courier new,courier,monospace\"><strong>Alerta de Posible Riesgo AML</strong></span></h2>\r\n\r\n<div style=\"text-align: right;\">\r\n<hr /><span style=\"font-family:courier new,courier,monospace\">Numero de Persona Involucrada:</span>variable_persona_nombre_completo</div>\r\n\r\n<div style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">Numero de Documento Involucrado:</span>variable_documento_codigo</div>\r\n\r\n<hr />\r\n<p style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">Fecha de Generaci&oacute;n:</span>variable_docto_fecha</p>\r\n\r\n<div style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">Hora de Generaci&oacute;n:</span>variable_docto_hora</div>\r\n\r\n<div style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">Nivel de Riesgo ponderado del Sistema: </span>variable_nivel_de_riesgo%</div>\r\n\r\n<div style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">Tipo de Riesgo:</span>variable_tipo_de_riesgo</div>\r\n\r\n<div style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">Clasificaci&oacute;n:</span>variable_clasificacion_de_riesgo</div>\r\n\r\n<div style=\"text-align: right;\"><span style=\"font-family:courier new,courier,monospace\">V&iacute;nculo de Alerta en el Sistema: &nbsp;<a href=\"variable_url_del_sistemafrmpld/estatus_de_alerta.frm.php?remote=true&amp;id=variable_codigo_de_alerta\">variable_codigo_de_alerta</a></span></div>\r\n\r\n<hr />\r\n<p style=\"text-align: right;\"><strong><span style=\"font-family:courier new,courier,monospace\">Notas:</span></strong></p>\r\n\r\n<hr />\r\n<p><span style=\"font-family:courier new,courier,monospace\">variable_mensaje_de_alerta</span></p>\r\n\r\n<hr />\r\n<div style=\"text-align: justify;\"><span style=\"font-family:courier new,courier,monospace\"><em>Este es un Aviso Automatizado por el Sistema de Alertas de SAFE-OSMS, como posible riesgo marcado, en ning&uacute;n caso se considera como un riesgo definitivo por lo que se necesita de su intervenci&oacute;n para verificarlo.</em></span></div>\r\n\r\n<hr />\r\n<p><span style=\"font-family:courier new,courier,monospace\">Sist