INSERT INTO `general_formulas` (`aplicado_a`, `estructura_de_la_formula`, `code_type`, `description_short`) VALUES ('formula_ide','$base_gravada = ($base_de_calculo - $excencion);\r\nif($base_gravada < 0){\r\n$base_gravada = 0;\r\n}\r\n$ide = ( $base_gravada * $tasa_ide);','php','Formula de Impuesto sobre Depositos en Efectivo'),('interes_moroso','if ($tipo_de_calculo == INTERES_POR_SALDO_HISTORICO ){\r\n	$interes_moroso = ($saldo_historico * $dias_morosos * ($tasa_moratorio * $factor_interes)) / EACP_DIAS_INTERES;\r\n} else {\r\n	$interes_moroso = ($saldo_insoluto * $dias_morosos * ($tasa_moratorio * $factor_interes)) / EACP_DIAS_INTERES;\r\n}\r\n\r\n','php',NULL),('interes_normal','if ($tipo_de_calculo == INTERES_POR_SALDO_HISTORICO ){\r\n $interes_normal = ($saldo_historico * $dias_normales * ($tasa_interes * $factor_interes)) / EACP_DIAS_INTERES;\r\n} else {\r\n $interes_normal = ($saldo_insoluto * $dias_normales * ($tasa_interes * $factor_interes)) / EACP_DIAS_INTERES;\r\n}\r\n','php',NULL),('interes_remanente','if ($tipo_de_calculo == INTERES_POR_SALDO_HISTORICO ){\r\n	$interes_remanente = ($saldo_insoluto * $dias_morosos * ($tasa_interes * $factor_interes)) / EACP_DIAS_INTERES;\r\n} else {\r\n	$interes_remanente = ($saldo_historico * $dias_morosos * ($tasa_interes * $factor_interes)) / EACP_DIAS_INTERES;\r\n}\r\n','php',NULL),('interes_remanente_vencido','if ($tipo_de_calculo == INTERES_POR_SALDO_HISTORICO ){\r\n	$interes_remanente_venc = ($saldo_historico * $dias_vencidos * ($tasa_interes * $factor_interes)) / EACP_DIAS_INTERES;\r\n} else {\r\n	$interes_remanente_venc = ($saldo_insoluto * $dias_vencidos * ($tasa_interes * $factor_interes)) / EACP_DIAS_INTERES;\r\n}\r\n','php',NULL),('interes_vencido','if ($tipo_de_calculo == INTERES_POR_SALDO_HISTORICO ){\r\n	$interes_vencido = ($saldo_historico * $dias_vencidos * ($tasa_moratorio * $factor_interes)) / EACP_DIAS_INTERES;\r\n} else {\r\n	$interes_vencido = ($saldo_insoluto * $dias_vencidos * ($tasa_moratorio * $factor_interes)) / EACP_DIAS_INTERES;\r\n}\r\n\r\n\r\n','php',NULL),('js_leasing_cot_vars','','js','Variables que Cambian los valores'),('php_interes_pago_flat_mod','','php','Modificador del Interes en pagos FLAT'),('php_mora_x_letra','$moratorio = ( $BASE_MORA * $DIAS_MORA * $TASA_MORA ) / 360;','php',''),('php_pena_x_letra','$DIAS_PENA = $DIAS_MORA; if ($DIAS_PENA >  0){ $moratorio=0;$penas=$TOTAL_MONTO_LETRA*$TASA_PENA; }','php',''),('rms_calculo_riesgo','$RIESGO = $PROBABILIDAD * $IMPACTO;','php','Formula de Calculo de Riesgo para el RMS'),('score_reference','ScoreNeto = (ScoreTiempo / maxScoreTiempo)  * ScoreOpinion;','js','Calificacion media de una Referencia según Opinion'),('sql_mora_x_letra','(letras.capital * DATEDIFF(getFechaDeCorte(), fecha_de_pago) * (creditos_solicitud.tasa_moratorio ))/getDivisorDeInteres()','mysql','');
