DROP TABLE IF EXISTS `general_municipios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `general_municipios` (
  `idgeneral_municipios` int(11) NOT NULL AUTO_INCREMENT,
  `clave_de_entidad` int(4) NOT NULL DEFAULT '4',
  `clave_de_municipio` int(6) NOT NULL DEFAULT '1',
  `nombre_del_municipio` varchar(100) DEFAULT NULL,
  `habitantes` float(14,2) DEFAULT NULL,
  `indice_de_marginacion` float(10,6) DEFAULT '0.000000',
  `grado_de_marginacion` varchar(20) DEFAULT 'Alto',
  `lugar_nacional` int(8) DEFAULT '0',
  PRIMARY KEY (`idgeneral_municipios`,`clave_de_entidad`,`clave_de_municipio`)
) ENGINE=InnoDB AUTO_INCREMENT=100000 DEFAULT CHARSET=utf8;
