/*!40000 ALTER TABLE `general_sql_stored` DISABLE KEYS */;
INSERT INTO `general_sql_stored` (`sqlcode`, `alias_sql`, `stringsql`) VALUES (1,'','SELECT trabajador_conceptos.numero, nominas_conceptos.descripcion, trabajador_conceptos.concepto, trabajador_conceptos.factor, trabajador_conceptos.cantidad, trabajador_conceptos.trabajador FROM trabajador_conceptos, nominas_conceptos WHERE trabajador_conceptos.concepto=nominas_conceptos.codigo'),(2,'','SELECT nominas_movimientos.*, nominas_conceptos.descripcion FROM nominas_movimientos, nominas_conceptos WHERE nominas_conceptos.codigo = nominas_movimientos.concepto '),(3,'','SELECT\r\n	`creditos_solicitud`.*,\r\n	`creditos_periocidadpagos`.`titulo_en_informe`,\r\n	`creditos_periocidadpagos`.\r\n	`tolerancia_en_dias_para_vencimiento`,\r\n	`creditos_tipoconvenio`.* \r\nFROM\r\n	`creditos_periocidadpagos` `creditos_periocidadpagos` \r\n		INNER JOIN `creditos_solicitud` `creditos_solicitud` \r\n		ON `creditos_periocidadpagos`.\r\n		`idcreditos_periocidadpagos` = `creditos_solicitud`.\r\n		`periocidad_de_pago` \r\n			INNER JOIN `creditos_tipoconvenio` \r\n			`creditos_tipoconvenio` \r\n			ON `creditos_tipoconvenio`.\r\n			`idcreditos_tipoconvenio` = `creditos_solicitud`\r\n			.`tipo_convenio`'),(4,'socios_simple','SELECT\r\n	`socios`.`codigo`,\r\n	`socios`.`nombre`,\r\n	`socios`.`dependencia`,\r\n	`socios`.`genero`,\r\n	`socios`.`tipo_ingreso` \r\nFROM\r\n	`socios` `socios`'),(5,'operaciones_simple','SELECT operaciones_mvtos.idoperaciones_mvtos AS \'control\', \r\noperaciones_mvtos.fecha_operacion AS \'fecha_operacion\', \r\noperaciones_mvtos.recibo_afectado AS \'recibo\', \r\noperaciones_mvtos.periodo_socio as \'parcialidad\', \r\noperaciones_tipos.descripcion_operacion AS \'tipo_operacion\', \r\n(operaciones_mvtos.afectacion_real * operaciones_mvtos.valor_afectacion) AS \'monto\', \r\noperaciones_mvtos.detalles, operaciones_mvtos.tipo_operacion\r\nFROM 	`operaciones_mvtos` `operaciones_mvtos` \r\n		INNER JOIN `operaciones_tipos` `operaciones_tipos` \r\n		ON `operaciones_mvtos`.`tipo_operacion` = `operaciones_tipos`.\r\n		`idoperaciones_tipos`'),(6,'socios_con_tipo_ingreso','SELECT socios_general.codigo AS \'codigo\', \r\nCONCAT(socios_general.apellidopaterno, \' \', socios_general.apellidomaterno, \' \', socios_general.nombrecompleto) AS \'nombre_completo\', \r\nsocios_tipoingreso.descripcion_tipoingreso AS \'tipo_de_ingreso\', \r\nsocios_grupossolidarios.nombre_gruposolidario AS \'grupo_solidario\' \r\n\r\nFROM 	`socios_general` `socios_general` \r\n		INNER JOIN `socios_grupossolidarios` `socios_grupossolidarios` \r\n		ON `socios_general`.`grupo_solidario` = `socios_grupossolidarios`.\r\n		`idsocios_grupossolidarios` \r\n			INNER JOIN `socios_tipoingreso` `socios_tipoingreso` \r\n			ON `socios_general`.`tipoingreso` = `socios_tipoingreso`.\r\n			`idsocios_tipoingreso`\r\n');
/*!40000 ALTER TABLE `general_sql_stored` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `general_structure`
--

DROP TABLE IF EXISTS `general_structure`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `general_structure` (
  `index_struct` int(11) NOT NULL AUTO_INCREMENT,
  `tabla` varchar(100) DEFAULT NULL,
  `campo` varchar(100) DEFAULT NULL,
  `valor` varchar(250) DEFAULT NULL,
  `tipo` varchar(20) DEFAULT NULL,
  `longitud` int(4) DEFAULT '0',
  `descripcion` varchar(200) DEFAULT NULL,
  `titulo` varchar(100) DEFAULT NULL,
  `control` enum('text','textarea','select','hidden') DEFAULT 'text',
  `sql_select` text,
  `orientacion` enum('izquierda','derecha') DEFAULT 'derecha',
  `order_index` int(10) unsigned NOT NULL DEFAULT '0',
  `script_field` mediumtext,
  `help_text` mediumtext,
  `tab_num` varchar(20) DEFAULT '' COMMENT 'ID DE TAB',
  `css_class` varchar(20) DEFAULT 'normalfield',
  `input_events` varchar(120) DEFAULT '',
  PRIMARY KEY (`index_struct`)
) ENGINE=InnoDB AUTO_INCREMENT=2414 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

