CREATE TABLE `general_sucursales` (
  `codigo_sucursal` varchar(10) NOT NULL,
  `nombre_sucursal` varchar(55) NOT NULL,
  `gerente_sucursal` bigint(20) DEFAULT '1',
  `caja_local_residente` int(4) DEFAULT '1',
  `titular_de_cobranza` bigint(20) DEFAULT '1',
  `titular_de_seguimiento` bigint(20) DEFAULT '1',
  `titular_de_contabilidad` bigint(20) DEFAULT '1',
  `titular_de_inventarios` bigint(20) DEFAULT '1',
  `titular_de_control_interno` bigint(20) DEFAULT '1',
  `titular_de_nominas` bigint(20) DEFAULT '1',
  `titular_de_cumplimiento` bigint(20) DEFAULT '1',
  `hora_de_inicio_de_operaciones` int(4) unsigned DEFAULT '8',
  `hora_de_fin_de_operaciones` int(4) unsigned DEFAULT '16',
  `calle` varchar(100) DEFAULT NULL,
  `numero_exterior` varchar(25) DEFAULT NULL,
  `numero_interior` varchar(25) DEFAULT NULL,
  `colonia` varchar(45) DEFAULT NULL,
  `codigo_postal` int(11) DEFAULT '1',
  `localidad` varchar(50) DEFAULT NULL,
  `municipio` varchar(50) DEFAULT NULL,
  `estado` varchar(50) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `fax` varchar(20) DEFAULT NULL,
  `clave_de_persona` bigint(20) DEFAULT NULL COMMENT 'numero de persona en la tabla personas',
  `clave_numerica` int(6) DEFAULT '0' COMMENT 'clave de sucursal segun la cnbv',
  `centro_de_costo` int(11) DEFAULT '0',
  `iddomicilio` int(8) DEFAULT NULL,
  `estatus` int(2) DEFAULT '1',
  PRIMARY KEY (`codigo_sucursal`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
