--
-- Table structure for table `operaciones_tipos`
--

DROP TABLE IF EXISTS `operaciones_tipos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `operaciones_tipos` (
  `idoperaciones_tipos` int(4) unsigned NOT NULL AUTO_INCREMENT COMMENT 'los numeros del 5000 al 5999 estan reservados a empresas especiales. 5101 5102 5103',
  `descripcion_operacion` varchar(100) NOT NULL DEFAULT '',
  `clasificacion` int(4) DEFAULT '0',
  `subclasificacion` int(4) DEFAULT '0',
  `cuenta_contable` varchar(100) DEFAULT NULL,
  `descripcion` varchar(100) DEFAULT NULL,
  `recibo_que_afecta` int(4) DEFAULT '99',
  `tipo_operacion` int(4) DEFAULT '0' COMMENT 'DEPRECATED',
  `visible_reporte` int(4) DEFAULT '1' COMMENT 'DEPRECATED',
  `class_efectivo` int(4) DEFAULT '1' COMMENT 'Clasificacion segun el Efectivo',
  `mvto_que_afecta` int(4) DEFAULT '99' COMMENT 'los numeros del 5000 al 5999 estan reservados a empresas especiales. 5101 5102 5103',
  `afectacion_en_recibo` int(4) DEFAULT '0',
  `afectacion_en_notificacion` int(4) unsigned NOT NULL DEFAULT '0',
  `producto_aplicable` int(4) unsigned NOT NULL DEFAULT '0',
  `constituye_fondo_automatico` enum('1','0') NOT NULL DEFAULT '1',
  `integra_vencido` enum('1','0') NOT NULL DEFAULT '1',
  `afectacion_en_sdpm` int(4) DEFAULT '0',
  `cargo_directo` int(2) DEFAULT '0' COMMENT '1=SI 0=NO',
  `codigo_de_valoracion` mediumtext NOT NULL,
  `periocidad_afectada` enum('ninguna','todas','vencimiento','periodico') NOT NULL DEFAULT 'ninguna',
  `integra_parcialidad` enum('1','0') NOT NULL DEFAULT '0',
  `es_estadistico` enum('1','0') NOT NULL DEFAULT '0',
  `formula_de_calculo` text,
  `formula_de_cancelacion` mediumtext,
  `importancia_de_neutralizacion` int(4) DEFAULT '0' COMMENT 'Orden en que se Cancela',
  `preservar_movimiento` enum('0','1') DEFAULT '1',
  `tasa_iva` float(8,3) DEFAULT '0.000',
  `nombre_corto` varchar(15) NOT NULL COMMENT 'capital intereses moratorios',
  `estatus` int(2) NOT NULL COMMENT '1activo',
  `precio` float(12,2) DEFAULT '0.00',
  PRIMARY KEY (`idoperaciones_tipos`)
) ENGINE=InnoDB AUTO_INCREMENT=9303 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

