INSERT INTO `operaciones_tipos` (`idoperaciones_tipos`, `descripcion_operacion`, `clasificacion`, `subclasificacion`, `cuenta_contable`, `descripcion`, `recibo_que_afecta`, `tipo_operacion`, `visible_reporte`, `class_efectivo`, `mvto_que_afecta`, `afectacion_en_recibo`, `afectacion_en_notificacion`, `producto_aplicable`, `constituye_fondo_automatico`, `integra_vencido`, `afectacion_en_sdpm`, `cargo_directo`, `codigo_de_valoracion`, `periocidad_afectada`, `integra_parcialidad`, `es_estadistico`, `formula_de_calculo`, `formula_de_cancelacion`, `importancia_de_neutralizacion`, `preservar_movimiento`, `tasa_iva`, `nombre_corto`, `estatus`, `precio`) VALUES (50,'CREDITOS AUTORIZADOS DE GRUPO',0,0,'$cuenta = \"NO_CONTABILIZAR\"; /*$cuenta = CUENTA_DE_CUADRE;*/','Operacion de Autorizaciones de Credito a Grupos',999,50,1,1,99,0,0,0,'1','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',1,0.00),(99,'NO DETERMINADO',99,99,'$cuenta = CUENTA_DE_CUADRE;','Ingresos no Clasificados',999,99,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',1,0.00),(110,'DESEMBOLSO DE CREDITO',2,1,'$cuenta = $cartera[\"capital_vigente_normal\"];','Operacion de Ministracion de Credito',999,110,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','0','','if ( !isset($Credito) ) {\r\n	$Credito          = new cCredito($docto, $socio);\r\n	$Credito->initCredito();\r\n}\r\n\r\n$Actualizado 	= array( \"saldo_actual\" => 0,\r\n			\"estatus_actual\" => 98);\r\n\r\n$Credito->setUpdate($Actualizado);',0,'0',0.000,'',1,0.00),(111,'TRASP.-CARTERA VIGENTE-VENCIDA',3,11,'$cuenta = $cartera[\"capital_vencido_normal\"];','Operacion de Credito a Cartera Vencida',999,111,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',1,0.00),(112,'PLANEACION DE CREDITOS(DEP)',0,0,'$cuenta = \"NO_CONTABILIZAR\"; /*$cuenta = CUENTA_DE_CUADRE;*/','Operacion de Planeacion de Creditos en Grupos',999,112,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',0,0.00),(113,'TRASP.-CARTERA VIGENTE-REESTRUCTURAS',0,0,'$cuenta = \"NO_CONTABILIZAR\"; /*$cuenta = CUENTA_DE_CUADRE;*/','',999,113,1,1,99,0,0,0,'1','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',1,0.00),(114,'TRASP.-CARTERA VENCIDA-VIGENTE',0,0,'$cuenta = $cartera[\"capital_vigente_normal\"];','',999,114,1,1,99,0,0,0,'1','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',1,0.00),(115,'TRASP.-CARTERA VIGENTE A MORA',0,0,'$cuenta = $cartera[\"capital_vigente_normal\"];','Operacion de Traspaso de Creditos Vigentes a Morosos',999,115,1,1,99,0,0,0,'1','1',0,0,'','ninguna','0','1','','',0,'0',0.000,'',1,0.00),(117,'DISPOSICION DE CREDITO',2,1,'$cuenta = $cartera[\"capital_vigente_normal\"];','Operacion de Aumento de Credito',999,117,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','0','','if ( !isset($Credito) ) { $Credito = new cCredito($docto, $socio);\r\n $Credito->initCredito(); }',0,'0',0.000,'',1,0.00),(120,'PAGO/ABONO AL CAPITAL',1,2,'$cuenta = $cartera[\"capital_vigente_normal\"];','Operacion de pago / abono al Capital de creditos',999,120,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','0','','if ( !isset($Credito) ){$Credito= new cCredito($docto, $socio); $Credito->init(); }; if ( $Credito->getNumeroDePlanDePagos()>0){ $xPP = new cParcialidadDeCredito($Credito->getClaveDePersona(), $Credito->getClaveDeCredito(), $parcialidad); $xPP->setClaveDePlan($Credito->getNumeroDePlanDePagos()); $xPP->setActualizarCapital($monto); if ( $PAGOS_SIN_CAPITAL == true){ $xPP->setActualInteresPropCred($socio, $docto, $parcialidad, $monto, $Credito->getSaldoActual(), true);} }',0,'0',0.000,'',1,0.00),(140,'PAGO DE INTERES',1,2,'$cuenta = $cartera[\"interes_vigente_normal\"];','Operacion de Pagos de Intereses de Creditos',999,140,1,1,99,0,0,0,'0','1',0,1,'','ninguna','0','0','','if ( !isset($Credito) ){$Credito= new cCredito($docto, $socio); $Credito->init(); }; if ( $Credito->getNumeroDePlanDePagos()>0){ $xPP = new cParcialidadDeCredito($Credito->getClaveDePersona(), $Credito->getClaveDeCredito(), $parcialidad); $xPP->setClaveDePlan($Credito->getNumeroDePlanDePagos()); $xPP->setActualizarInteres($monto);}',0,'0',0.000,'',1,0.00),(141,'PAGO DE INTERES MORATORIO',1,2,'$cuenta = $cartera[\"contable_intereses_moratorios\"];','Operacion de Pago de Interes Moratorio de Creditos',999,141,1,1,99,1,0,0,'0','1',0,1,'if ( !isset($Credito) ){ $Credito = new cCredito($docto, $socio); $Credito->initCredito(); }\r\n\r\n$DCred		= $Credito->getDatosDeCredito();\r\n$id			= $DCred[\"interes_moratorio_devengado\"] + $monto;\r\n$ip			= $DCred[\"interes_moratorio_pagado\"] - $monto;\r\n\r\n$Actualizado = array( \"interes_normal_pagado\" => $ip,\r\n		\"interes_normal_devengado\" => $id );\r\n\r\n$Credito->setUpdate($Actualizado);\r\n$FechaInicial		= $Credito->getFechaDeMinistracion();\r\n$FechaFinal		= fechasys();\r\n$solicitud		= $docto;\r\n\r\n$msg			.= $xCUtils->setGenerarMvtoFinDeMes($FechaInicial, $FechaFinal, $solicitud, true);\r\n$msg			.= $xCUtils->setReestructurarSDPM(false, $solicitud);\r\n$msg			.= $xCUtils->setRegenerarInteresDevengado( $solicitud, $FechaInicial, $FechaFinal );\r\n$msg			.= $xCUtils->setAcumularIntereses(false, $solicitud);\r\n','ninguna','0','0','','if ( !isset($Credito) ){ $Credito = new cCredito($docto, $socio);$Credito->initCredito(); }\r\n',0,'0',0.000,'',1,0.00),(142,'PAGO DE INTERES MIN. COMPENSATORIO',0,0,'$cuenta = $cartera[\"contable_intereses_cobrados\"];','Operacion de pago Minimo Compensatorio de Interes en Creditos',999,142,1,1,99,1,0,0,'0','1',0,0,'$base_iva_intereses = $base_iva_intereses + $monto;','ninguna','0','0','','',21,'0',0.000,'',1,0.00),(143,'PAGO DE INTERESES VENCIDOS',0,0,'$cuenta = $cartera[\"interes_vigente_normal\"];','',999,143,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','0','','',0,'0',0.000,'',1,0.00),(145,'PAGO DE COMISIONES POR SEGUIMIENTO',1,11,'$cuenta = \"5404\";','Operacion de Pago de Comision por seguimiento',999,145,1,1,99,0,0,0,'0','1',0,0,'','ninguna','0','0','','',0,'0',0.000,'',1,0.00),(146,'PAGO DE COMISIONES VARIAS',0,0,'$cuenta = \"5404\";','',9