--

DROP TABLE IF EXISTS `originacion_leasing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `originacion_leasing` (
  `idoriginacion_leasing` int(11) NOT NULL AUTO_INCREMENT,
  `fecha_origen` date DEFAULT '0000-00-00',
  `persona` bigint(20) DEFAULT '0' COMMENT 'persona asignada',
  `credito` bigint(20) DEFAULT '0' COMMENT 'persona asignada',
  `marca` int(4) DEFAULT '1' COMMENT '1 por defecto',
  `modelo` varchar(100) DEFAULT NULL,
  `annio` varchar(6) DEFAULT NULL,
  `tipo_leasing` int(2) DEFAULT '1' COMMENT '1 puro 2 financiero',
  `tipo_uso` int(4) DEFAULT '0',
  `tipo_rac` int(4) DEFAULT '0',
  `tipo_gps` int(4) DEFAULT '1' COMMENT 'clave de equipo en renta',
  `originador` int(8) DEFAULT '0' COMMENT 'puede ser el ID de Agencia o Empleado',
  `suboriginador` int(8) DEFAULT '0' COMMENT 'A quien se destina la comision o persona que origina',
  `precio_vehiculo` double(18,2) DEFAULT '0.00' COMMENT 'Precio con Impuestos Incluidos',
  `monto_aliado` double(18,2) DEFAULT '0.00' COMMENT 'Equipo Aliado',
  `monto_accesorios` double(18,2) DEFAULT '0.00',
  `monto_anticipo` double(18,2) DEFAULT '0.00',
  `monto_tenencia` double(18,2) DEFAULT NULL,
  `monto_garantia` double(18,2) DEFAULT '0.00' COMMENT 'Garantia Extendida Financiada',
  `monto_mtto` double(18,2) DEFAULT '0.00',
  `comision_originador` float(6,4) DEFAULT '0.0000',
  `comision_apertura` float(6,4) DEFAULT '0.0000',
  `tasa_iva` float(6,4) DEFAULT '0.0000',
  `tasa_compra` float(6,4) DEFAULT '0.0000',
  `financia_seguro` int(2) DEFAULT '0',
  `financia_tenencia` int(2) DEFAULT '0',
  `domicilia` int(2) DEFAULT '0' COMMENT 'Si domicilia el Pago',
  `paso_proceso` int(4) DEFAULT '0' COMMENT 'Pasos del proceso de Credito',
  `describe_aliado` varchar(150) DEFAULT '',
  `usuario` int(8) DEFAULT '0' COMMENT 'usuario que origina',
  `nombre_cliente` varchar(150) DEFAULT '',
  `nombre_atn` varchar(150) DEFAULT '',
  `oficial` int(8) DEFAULT '0',
  `total_credito` double(18,2) DEFAULT '0.00',
  `segmento` int(4) DEFAULT '0',
  `entidadfederativa` int(4) DEFAULT '0' COMMENT 'Entidad en que transita el vehiculo',
  `plazo` int(4) DEFAULT '0',
  `tasa_credito` float(6,4) DEFAULT '0.0000',
  `tasa_tiie` float(6,4) DEFAULT '0.0000',
  `monto_gps` double(18,2) DEFAULT '0.00',
  `monto_directo` double(18,2) DEFAULT '0.00' COMMENT 'Monto no financiado',
  `monto_seguro` double(18,2) DEFAULT '0.00',
  `monto_placas` double(18,2) DEFAULT '0.00',
  `monto_gestoria` double(18,2) DEFAULT '0.00',
  `monto_notario` double(18,2) DEFAULT '0.00',
  `monto_residual` double(18,2) DEFAULT '0.00',
  `cuota_vehiculo` double(18,2) DEFAULT '0.00',
  `cuota_aliado` double(18,2) DEFAULT '0.00',
  `cuota_accesorios` double(18,2) DEFAULT '0.00',
  `cuota_tenencia` double(18,2) DEFAULT '0.00',
  `cuota_mtto` double(18,2) DEFAULT '0.00',
  `cuota_gps` double(18,2) DEFAULT '0.00',
  `cuota_seguro` double(18,2) DEFAULT '0.00',
  `monto_comision` double(18,2) DEFAULT '0.00' COMMENT 'Monto de comision de apertura',
  `monto_originador` double(18,2) DEFAULT '0.00' COMMENT 'Monto pagado al Originador',
  `cuota_garantia` double(18,2) DEFAULT '0.00',
  `es_moral` int(2) DEFAULT '0' COMMENT 'Es persona moral',
  `estatus` int(2) DEFAULT '1',
  `renta_deposito` double(18,2) DEFAULT '0.00',
  `renta_proporcional` double(18,2) DEFAULT '0.00',
  `renta_extra` double(18,2) DEFAULT '0.00',
  `residuales` varchar(60) DEFAULT '' COMMENT 'resiidual formato PERIODICIDAD separador  PLAZO separador TASA coma',
  `mail` varchar(50) DEFAULT '',
  `tel` varchar(15) DEFAULT '',
  `cuota_iva` double(18,2) DEFAULT '0.00',
  `vecs` varchar(60) DEFAULT '',
  `tasas` varchar(60) DEFAULT '' COMMENT 'tasas modificadas',
  `montoajuste` float(10,2) DEFAULT '0.00',
  `administrado` int(2) DEFAULT '0' COMMENT 'Está o No Administrado',
  `opts` varchar(100) DEFAULT '',
  `noivarent` int(2) DEFAULT '0' COMMENT 'renta sin iva',
  `com_agencia` float(6,4) DEFAULT '0.0000',
  `gps_list` varchar(60) DEFAULT '',
  `montocom_agen` float(10,2) DEFAULT '0.00',
  PRIMARY KEY (`idoriginacion_leasing`),
  UNIQUE KEY `idoriginacion_leasing_UNIQUE` (`idoriginacion_leasing`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
