DROP TABLE IF EXISTS `personas_ae_scian`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `personas_ae_scian` (
  `clave_interna` bigint(20) NOT NULL,
  `clave_de_actividad` varchar(20) DEFAULT '',
  `nombre_de_la_actividad` varchar(200) DEFAULT '',
